using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RefreshingHeadbuttCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/RefreshingHeadbuttCustomDescription", order = 0)]
public class RefreshingHeadbuttCustomDescription : PurifyMinimunWaveCustomDescription
{
	protected override string GetExtraActionDescription(BattleAction battleAction, string amountModified)
	{
		return (battleAction as RefreshingHeadbuttAction).RefreshAction.GetActionDescription(EffectsValues.NO_VALUE).RemoveLast();
	}
}
